//! Shared domain types generated by hand from `docs/contracts/README.md`:
//! id prefixes, the scope list with its flags, and the human role bundles.
//!
//! Every name here is spelled exactly as in the contracts; a scope or prefix
//! that is not in the README does not belong in this crate.

use serde::{Deserialize, Serialize};
use std::fmt;
use std::time::{SystemTime, UNIX_EPOCH};

/// Crockford base32 alphabet used by ULIDs.
const CROCKFORD: &[u8; 32] = b"0123456789ABCDEFGHJKMNPQRSTVWXYZ";

/// Resource id prefixes (README "Identifiers").
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Prefix {
    Cluster,
    Node,
    Project,
    Vm,
    User,
    Request,
    Lease,
    Event,
    Provider,
    Session,
    NodeJoinToken,
    Agent,
    AgentKey,
    AccessToken,
    Grant,
    Approval,
    Incident,
    Webhook,
    WebhookDelivery,
}

impl Prefix {
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Cluster => "cls",
            Self::Node => "nod",
            Self::Project => "prj",
            Self::Vm => "vm",
            Self::User => "usr",
            Self::Request => "req",
            Self::Lease => "lse",
            Self::Event => "evt",
            Self::Provider => "prv",
            // Session rows have no contract prefix; the id never leaves the
            // server and only names the `sessions` row.
            Self::Session => "ses",
            Self::NodeJoinToken => "njt",
            Self::Agent => "agt",
            Self::AgentKey => "akey",
            Self::AccessToken => "atk",
            Self::Grant => "grt",
            Self::Approval => "apr",
            Self::Incident => "inc",
            Self::Webhook => "whk",
            Self::WebhookDelivery => "whd",
        }
    }
}

/// A new `<prefix>_<ULID>` id: 48 bits of milliseconds since the Unix epoch
/// followed by 80 random bits, in Crockford base32 (26 characters).
///
/// # Panics
///
/// Panics if the operating system's random generator fails, which leaves no
/// safe way to mint an id.
#[must_use]
pub fn new_id(prefix: Prefix) -> String {
    let millis = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |d| d.as_millis());
    let mut random = [0u8; 10];
    getrandom::fill(&mut random).expect("OS random generator");
    let mut value: u128 = (millis & 0xFFFF_FFFF_FFFF) << 80;
    for (i, byte) in random.iter().enumerate() {
        value |= u128::from(*byte) << (8 * (9 - i));
    }
    let mut out = String::with_capacity(prefix.as_str().len() + 27);
    out.push_str(prefix.as_str());
    out.push('_');
    for i in (0..26).rev() {
        let index = ((value >> (5 * i)) & 0x1F) as usize;
        out.push(char::from(CROCKFORD[index]));
    }
    out
}

/// A new bearer secret `<prefix>_<26 Crockford base32 characters>`, all of
/// them random (130 bits), so it matches the same pattern as an id but carries
/// no timestamp. Used for agent access tokens (`atk_`), whose response pattern
/// in `openapi.yaml` is the id pattern. Never use [`new_id`] for a secret: its
/// first ten characters are the creation time.
///
/// # Panics
///
/// Panics if the operating system's random generator fails.
#[must_use]
pub fn new_secret(prefix: Prefix) -> String {
    let mut random = [0u8; 17];
    getrandom::fill(&mut random).expect("OS random generator");
    let mut value: u128 = 0;
    for byte in &random[..16] {
        value = (value << 8) | u128::from(*byte);
    }
    let mut out = String::with_capacity(prefix.as_str().len() + 27);
    out.push_str(prefix.as_str());
    out.push('_');
    // 25 characters from the first 125 bits, the last from the 17th byte.
    for i in (0..25).rev() {
        let index = ((value >> (5 * i + 3)) & 0x1F) as usize;
        out.push(char::from(CROCKFORD[index]));
    }
    out.push(char::from(CROCKFORD[usize::from(random[16] & 0x1F)]));
    out
}

/// Whether `id` is `<prefix>_` followed by 26 Crockford base32 characters,
/// the pattern every id parameter in `openapi.yaml` uses.
#[must_use]
pub fn is_id(prefix: Prefix, id: &str) -> bool {
    let Some(rest) = id
        .strip_prefix(prefix.as_str())
        .and_then(|r| r.strip_prefix('_'))
    else {
        return false;
    };
    rest.len() == 26 && rest.bytes().all(|b| CROCKFORD.contains(&b))
}

/// Every scope in README "Scopes", in table order.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum Scope {
    #[serde(rename = "cluster:read")]
    ClusterRead,
    #[serde(rename = "node:read")]
    NodeRead,
    #[serde(rename = "node:enroll")]
    NodeEnroll,
    #[serde(rename = "node:remove")]
    NodeRemove,
    #[serde(rename = "node:fence_ack")]
    NodeFenceAck,
    #[serde(rename = "node:roles")]
    NodeRoles,
    #[serde(rename = "node:declare_lost")]
    NodeDeclareLost,
    #[serde(rename = "project:read")]
    ProjectRead,
    #[serde(rename = "project:write")]
    ProjectWrite,
    #[serde(rename = "project:delete")]
    ProjectDelete,
    #[serde(rename = "vm:read")]
    VmRead,
    #[serde(rename = "vm:create")]
    VmCreate,
    #[serde(rename = "vm:start")]
    VmStart,
    #[serde(rename = "vm:stop")]
    VmStop,
    #[serde(rename = "vm:delete")]
    VmDelete,
    #[serde(rename = "vm:console")]
    VmConsole,
    #[serde(rename = "app:read")]
    AppRead,
    #[serde(rename = "app:create")]
    AppCreate,
    #[serde(rename = "app:update")]
    AppUpdate,
    #[serde(rename = "app:restart")]
    AppRestart,
    #[serde(rename = "app:redeploy")]
    AppRedeploy,
    #[serde(rename = "app:deploy")]
    AppDeploy,
    #[serde(rename = "app:start")]
    AppStart,
    #[serde(rename = "app:stop")]
    AppStop,
    #[serde(rename = "app:delete")]
    AppDelete,
    #[serde(rename = "app:logs")]
    AppLogs,
    #[serde(rename = "app:terminal")]
    AppTerminal,
    #[serde(rename = "app:failover")]
    AppFailover,
    #[serde(rename = "app:delete_quarantine")]
    AppDeleteQuarantine,
    #[serde(rename = "backup:read")]
    BackupRead,
    #[serde(rename = "backup:write")]
    BackupWrite,
    #[serde(rename = "backup:restore")]
    BackupRestore,
    #[serde(rename = "backup:manage")]
    BackupManage,
    #[serde(rename = "agent:read")]
    AgentRead,
    #[serde(rename = "agent:write")]
    AgentWrite,
    #[serde(rename = "grant:read")]
    GrantRead,
    #[serde(rename = "grant:write")]
    GrantWrite,
    #[serde(rename = "approval:read")]
    ApprovalRead,
    #[serde(rename = "approval:create")]
    ApprovalCreate,
    #[serde(rename = "approval:decide")]
    ApprovalDecide,
    #[serde(rename = "incident:read")]
    IncidentRead,
    #[serde(rename = "incident:resolve")]
    IncidentResolve,
    #[serde(rename = "audit:read")]
    AuditRead,
    #[serde(rename = "event:read")]
    EventRead,
    #[serde(rename = "webhook:read")]
    WebhookRead,
    #[serde(rename = "webhook:write")]
    WebhookWrite,
    #[serde(rename = "provider:manage")]
    ProviderManage,
    #[serde(rename = "user:read")]
    UserRead,
    #[serde(rename = "user:write")]
    UserWrite,
}

impl Scope {
    /// Every scope, in README table order.
    pub const ALL: [Scope; 49] = [
        Self::ClusterRead,
        Self::NodeRead,
        Self::NodeEnroll,
        Self::NodeRemove,
        Self::NodeFenceAck,
        Self::NodeRoles,
        Self::NodeDeclareLost,
        Self::ProjectRead,
        Self::ProjectWrite,
        Self::ProjectDelete,
        Self::VmRead,
        Self::VmCreate,
        Self::VmStart,
        Self::VmStop,
        Self::VmDelete,
        Self::VmConsole,
        Self::AppRead,
        Self::AppCreate,
        Self::AppUpdate,
        Self::AppRestart,
        Self::AppRedeploy,
        Self::AppDeploy,
        Self::AppStart,
        Self::AppStop,
        Self::AppDelete,
        Self::AppLogs,
        Self::AppTerminal,
        Self::AppFailover,
        Self::AppDeleteQuarantine,
        Self::BackupRead,
        Self::BackupWrite,
        Self::BackupRestore,
        Self::BackupManage,
        Self::AgentRead,
        Self::AgentWrite,
        Self::GrantRead,
        Self::GrantWrite,
        Self::ApprovalRead,
        Self::ApprovalCreate,
        Self::ApprovalDecide,
        Self::IncidentRead,
        Self::IncidentResolve,
        Self::AuditRead,
        Self::EventRead,
        Self::WebhookRead,
        Self::WebhookWrite,
        Self::ProviderManage,
        Self::UserRead,
        Self::UserWrite,
    ];

    /// The wire form, for example `vm:create`.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::ClusterRead => "cluster:read",
            Self::NodeRead => "node:read",
            Self::NodeEnroll => "node:enroll",
            Self::NodeRemove => "node:remove",
            Self::NodeFenceAck => "node:fence_ack",
            Self::NodeRoles => "node:roles",
            Self::NodeDeclareLost => "node:declare_lost",
            Self::ProjectRead => "project:read",
            Self::ProjectWrite => "project:write",
            Self::ProjectDelete => "project:delete",
            Self::VmRead => "vm:read",
            Self::VmCreate => "vm:create",
            Self::VmStart => "vm:start",
            Self::VmStop => "vm:stop",
            Self::VmDelete => "vm:delete",
            Self::VmConsole => "vm:console",
            Self::AppRead => "app:read",
            Self::AppCreate => "app:create",
            Self::AppUpdate => "app:update",
            Self::AppRestart => "app:restart",
            Self::AppRedeploy => "app:redeploy",
            Self::AppDeploy => "app:deploy",
            Self::AppStart => "app:start",
            Self::AppStop => "app:stop",
            Self::AppDelete => "app:delete",
            Self::AppLogs => "app:logs",
            Self::AppTerminal => "app:terminal",
            Self::AppFailover => "app:failover",
            Self::AppDeleteQuarantine => "app:delete_quarantine",
            Self::BackupRead => "backup:read",
            Self::BackupWrite => "backup:write",
            Self::BackupRestore => "backup:restore",
            Self::BackupManage => "backup:manage",
            Self::AgentRead => "agent:read",
            Self::AgentWrite => "agent:write",
            Self::GrantRead => "grant:read",
            Self::GrantWrite => "grant:write",
            Self::ApprovalRead => "approval:read",
            Self::ApprovalCreate => "approval:create",
            Self::ApprovalDecide => "approval:decide",
            Self::IncidentRead => "incident:read",
            Self::IncidentResolve => "incident:resolve",
            Self::AuditRead => "audit:read",
            Self::EventRead => "event:read",
            Self::WebhookRead => "webhook:read",
            Self::WebhookWrite => "webhook:write",
            Self::ProviderManage => "provider:manage",
            Self::UserRead => "user:read",
            Self::UserWrite => "user:write",
        }
    }

    /// Parses a scope string exactly as README "Scopes" spells it. Wildcards
    /// such as `app:*` are not scopes and return `None`.
    #[must_use]
    pub fn parse(value: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|scope| scope.as_str() == value)
    }

    /// README "Scopes": destructive scopes need JIT approval for agents.
    #[must_use]
    pub const fn is_destructive(self) -> bool {
        matches!(
            self,
            Self::NodeRemove
                | Self::ProjectDelete
                | Self::VmDelete
                | Self::AppDelete
                | Self::BackupRestore
                | Self::AppFailover
                | Self::AppDeleteQuarantine
        )
    }

    /// README "Scopes": human-only scopes never appear in an agent's grant.
    #[must_use]
    pub const fn is_human_only(self) -> bool {
        matches!(
            self,
            Self::NodeEnroll
                | Self::NodeRemove
                | Self::NodeFenceAck
                | Self::NodeRoles
                | Self::NodeDeclareLost
                | Self::AgentWrite
                | Self::GrantWrite
                | Self::ApprovalDecide
                | Self::WebhookWrite
                | Self::ProviderManage
                | Self::UserRead
                | Self::UserWrite
                | Self::AppTerminal
                | Self::AppDeleteQuarantine
                | Self::BackupManage
        )
    }

    /// Whether the verb is `read`.
    #[must_use]
    pub fn is_read(self) -> bool {
        self.as_str().ends_with(":read")
    }
}

impl fmt::Display for Scope {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// Human roles (permission-model.md section 3): fixed scope bundles.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Role {
    Owner,
    Operator,
    Viewer,
}

impl Role {
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Owner => "owner",
            Self::Operator => "operator",
            Self::Viewer => "viewer",
        }
    }

    /// Parses the `users.role` column.
    #[must_use]
    pub fn parse(value: &str) -> Option<Self> {
        match value {
            "owner" => Some(Self::Owner),
            "operator" => Some(Self::Operator),
            "viewer" => Some(Self::Viewer),
            _ => None,
        }
    }

    /// `owner` holds every scope, `operator` every scope except `user:write`
    /// and `backup:manage` (the recovery key opens every backup, ADR 0147),
    /// `viewer` every `:read` scope plus `app:logs`. `user:read` is a `:read`
    /// scope, so every role holds it.
    #[must_use]
    pub fn holds(self, scope: Scope) -> bool {
        match self {
            Self::Owner => true,
            Self::Operator => scope != Scope::UserWrite && scope != Scope::BackupManage,
            Self::Viewer => scope.is_read() || scope == Scope::AppLogs,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids_match_the_contract_pattern() {
        for prefix in [Prefix::Vm, Prefix::Project, Prefix::Request, Prefix::User] {
            let id = new_id(prefix);
            assert!(is_id(prefix, &id), "{id}");
        }
        assert!(!is_id(Prefix::Vm, "vm_01JC9Z6Q5W8N3K4T7R2M1XHB0"));
        assert!(!is_id(Prefix::Vm, "vm_01JC9Z6Q5W8N3K4T7R2M1XHB0I"));
        assert!(!is_id(Prefix::Vm, "prj_01JC9Z6Q5W8N3K4T7R2M1XHB0D"));
    }

    #[test]
    fn secrets_match_the_id_pattern_and_differ() {
        let a = new_secret(Prefix::AccessToken);
        let b = new_secret(Prefix::AccessToken);
        assert!(is_id(Prefix::AccessToken, &a), "{a}");
        assert_ne!(a, b);
    }

    #[test]
    fn ids_sort_by_creation_time() {
        let a = new_id(Prefix::Vm);
        std::thread::sleep(std::time::Duration::from_millis(2));
        let b = new_id(Prefix::Vm);
        assert!(a < b);
    }

    #[test]
    fn scopes_equal_the_readme_table() {
        let readme = include_str!("../../../docs/contracts/README.md");
        let table = readme
            .split("### Scopes\n")
            .nth(1)
            .and_then(|rest| rest.split("\n### ").next())
            .expect("README Scopes section");
        let listed: Vec<&str> = table
            .lines()
            .filter_map(|line| line.strip_prefix("| `"))
            .filter_map(|line| line.split('`').next())
            .collect();
        let ours: Vec<&str> = Scope::ALL.iter().map(|s| s.as_str()).collect();
        assert_eq!(listed, ours);
        for scope in Scope::ALL {
            let flags = table
                .lines()
                .find(|line| line.starts_with(&format!("| `{}`", scope.as_str())))
                .expect("row");
            assert_eq!(
                flags.contains("human-only"),
                scope.is_human_only(),
                "{scope}"
            );
            assert_eq!(
                flags.contains("destructive"),
                scope.is_destructive(),
                "{scope}"
            );
        }
    }

    #[test]
    fn role_bundles_follow_the_permission_model() {
        assert!(Role::Owner.holds(Scope::UserWrite));
        assert!(!Role::Operator.holds(Scope::UserWrite));
        assert!(Role::Operator.holds(Scope::NodeFenceAck));
        assert!(Role::Operator.holds(Scope::NodeRoles));
        assert!(Role::Operator.holds(Scope::NodeDeclareLost));
        assert!(!Role::Viewer.holds(Scope::NodeDeclareLost));
        assert!(Role::Viewer.holds(Scope::VmRead));
        assert!(Role::Viewer.holds(Scope::AppLogs));
        assert!(!Role::Viewer.holds(Scope::VmCreate));
        assert!(!Role::Viewer.holds(Scope::ProviderManage));
        assert!(Role::Operator.holds(Scope::UserRead));
        assert!(Role::Viewer.holds(Scope::UserRead));
        assert!(!Role::Viewer.holds(Scope::UserWrite));
        assert!(Role::Operator.holds(Scope::AppTerminal));
        assert!(Role::Operator.holds(Scope::VmConsole));
        assert!(!Role::Viewer.holds(Scope::AppTerminal));
        assert!(!Role::Viewer.holds(Scope::VmConsole));
        assert_eq!(Scope::ALL.iter().filter(|s| s.is_human_only()).count(), 15);
        assert_eq!(Scope::ALL.iter().filter(|s| s.is_destructive()).count(), 7);
        assert!(Role::Owner.holds(Scope::BackupManage));
        assert!(!Role::Operator.holds(Scope::BackupManage));
        assert!(Role::Operator.holds(Scope::BackupRestore));
        assert!(Role::Operator.holds(Scope::AppFailover));
        assert!(Role::Operator.holds(Scope::AppDeleteQuarantine));
        assert!(!Role::Viewer.holds(Scope::AppFailover));
        assert!(Role::Viewer.holds(Scope::BackupRead));
        assert!(!Role::Viewer.holds(Scope::BackupWrite));
    }
}
